:host { font-family: var(--body, Geist, Arial, sans-serif); color: var(--ink, #191c26); } :focus-visible { outline: 3px solid var(--blue, #3555ed); outline-offset: 5px; } input:focus-visible { outline-offset: 2px; }
.ds-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  min-height: 58px;
  padding: 14px 24px;
  border: 1px solid #1b1b1b;
  border-radius: 10px;
  background: #fff;
  box-shadow: 0 4px 0 #1b1b1b;
  font-size: 16px;
  font-weight: 550;
  line-height: 1.6;
  text-align: center;
  transition:
    transform 0.2s var(--ease),
    box-shadow 0.2s var(--ease),
    background 0.2s;
}
.ds-button:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 0 #1b1b1b;
  background: #f6f7fb;
}
.ds-button:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 #1b1b1b;
}
.ds-button.ds-primary {
  background: var(--blue);
  color: #fff;
  border-color: var(--blue-deep);
  box-shadow: 0 4px 0 var(--blue-deep);
}
.ds-button.ds-primary:hover {
  background: #2946d8;
  box-shadow: 0 6px 0 var(--blue-deep);
}
.ds-button.ds-primary:active {
  box-shadow: 0 1px 0 var(--blue-deep);
}
.ds-dark-section .ds-button {
  margin-block-start: 32px;
  color: var(--ink);
}
