.ds-nav-wrap {
  position: relative;
  width: min(var(--container), 100%);
  min-height: 80px;
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 12px 28px;
  border: 1px solid #171717;
  border-radius: 4px;
  background: #fff;
  box-shadow: 4px 4px 0 #070707;
}
.ds-desktop-nav {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 23px;
  flex: 1;
  white-space: nowrap;
}
.ds-desktop-nav > a, .ds-nav-dropdown > summary {
  padding-block: 13px;
  color: var(--muted);
  font-weight: 550;
  cursor: pointer;
}
.ds-desktop-nav > a:hover, .ds-nav-dropdown[open] > summary {
  color: var(--blue);
}
.ds-plus {
  display: inline-block;
  font-size: 20px;
  font-weight: 500;
  margin-inline-start: 5px;
  transition: transform 0.2s;
}
.ds-nav-dropdown[open] .ds-plus {
  transform: rotate(45deg);
}
.ds-mega-menu {
  position: absolute;
  inset-block-start: calc(100% + 1px);
  inset-inline: 0;
  background: #fff;
  border: 1px solid #171717;
  border-radius: 0 0 12px 12px;
  box-shadow: 0 20px 32px #101b321a;
  white-space: normal;
  animation: menu-in 0.25s var(--ease);
}
.ds-compact-mega {
  inset-inline-start: auto;
  inset-inline-end: 130px;
  width: 390px;
  padding: 15px;
}
.ds-compact-mega > a {
  display: block;
  padding: 15px;
  border-radius: 6px;
  font-size: 16px;
}
.ds-compact-mega > a:hover {
  background: var(--pale-blue);
}
.ds-compact-mega small {
  display: block;
  color: var(--muted);
  font-size: 14px;
  margin-block-start: 5px;
}
.ds-site-header.ds-scrolled .ds-nav-wrap {
  border: 0;
  box-shadow: none;
  border-radius: 0;
}
html[lang="fa"] .ds-desktop-nav {
  gap: 19px;
}
html[lang="fa"] .ds-desktop-nav > a, html[lang="fa"] .ds-nav-dropdown > summary {
  font-size: 15px;
}
